/**
 * Source API — legacy stack.
 *
 * meadow-endpoints 2.1.1 / meadow 1.0.35 / orator 2.0.10 / restify 6.4.0 over
 * MySQL, matching the generation the Headlight API runs in production.  MySQL
 * because meadow 1.0.x ships no MSSQL or PostgreSQL provider.
 */
var libMySQL2 = require('mysql2');
var libFable = require('fable');
var libOrator = require('orator');
var libMeadow = require('meadow');
var libMeadowEndpoints = require('meadow-endpoints');

var _Model = require('../shared/Model-Book.json');

var _Config = (
	{
		Host: process.env.MYSQL_HOST || 'mysql',
		Port: parseInt(process.env.MYSQL_PORT, 10) || 3306,
		User: process.env.MYSQL_USER || 'root',
		Password: process.env.MYSQL_PASSWORD || '',
		Database: process.env.MYSQL_DATABASE || 'source2x',
		APIPort: parseInt(process.env.API_PORT, 10) || 8086
	});

var _Settings = (
	{
		Product: 'CloneHarness-Source2x',
		ProductVersion: '1.0.0',
		APIServerPort: _Config.APIPort,
		MeadowProvider: 'MySQL',
		LogStreams: [ { streamtype: 'console' } ],
		MySQL:
			{
				Server: _Config.Host,
				Port: _Config.Port,
				User: _Config.User,
				Password: _Config.Password,
				Database: _Config.Database,
				ConnectionPoolLimit: 5
			}
	});

// meadow 1.0.x has no DDL support, so the source table is created directly.
var CREATE_TABLE_SQL =
	'CREATE TABLE IF NOT EXISTS Book (' +
	'  IDBook INT UNSIGNED NOT NULL AUTO_INCREMENT,' +
	'  GUIDBook CHAR(128) NOT NULL DEFAULT \'\',' +
	'  CreateDate DATETIME,' +
	'  CreatingIDUser INT NOT NULL DEFAULT 0,' +
	'  UpdateDate DATETIME,' +
	'  UpdatingIDUser INT NOT NULL DEFAULT 0,' +
	'  Deleted TINYINT NOT NULL DEFAULT 0,' +
	'  DeleteDate DATETIME,' +
	'  DeletingIDUser INT NOT NULL DEFAULT 0,' +
	'  Title VARCHAR(200) NOT NULL DEFAULT \'\',' +
	'  PRIMARY KEY (IDBook)' +
	') ENGINE=InnoDB DEFAULT CHARSET=utf8;';

var _Pool = libMySQL2.createPool(
	{
		connectionLimit: _Settings.MySQL.ConnectionPoolLimit,
		host: _Config.Host,
		port: _Config.Port,
		user: _Config.User,
		password: _Config.Password,
		database: _Config.Database,
		// foxhound emits :name placeholders; without this mysql2 leaves them unbound.
		namedPlaceholders: true
	});

_Pool.query(CREATE_TABLE_SQL,
	function (pTableError)
	{
		if (pTableError)
		{
			console.error('Source 2.x could not create the Book table: ' + pTableError.message);
			return process.exit(1);
		}

		var _Fable = libFable.new(_Settings);
		_Fable.MeadowMySQLConnectionPool = _Pool;

		var _Meadow = libMeadow.new(_Fable, 'Book').loadFromPackageObject(_Model.Tables.Book.MeadowSchema);
		var _MeadowEndpoints = libMeadowEndpoints.new(_Meadow);

		var _Orator = libOrator.new(_Settings);

		_Orator.startWebServer(
			function ()
			{
				// meadow-endpoints 2.x authenticates off a session that
				// orator-session supplies in production; the harness runs
				// unauthenticated, so every request gets an administrator
				// session before the endpoint authenticators look at it.
				_Orator.webServer.use(
					function (pRequest, pResponse, fNext)
					{
						pRequest.UserSession = { LoggedIn: true, UserID: 1, CustomerID: 1, UserRoleIndex: 5 };
						return fNext();
					});

				_MeadowEndpoints.connectRoutes(_Orator.webServer);
				_Fable.log.info('Source 2.x API listening on ' + _Config.APIPort + ' over MySQL [' + _Config.Database + '].');
			});
	});
